package com.videomind.module.auth;import com.videomind.common.api.ApiResponse;import jakarta.servlet.http.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.Map;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/auth")public class AuthController{private final AuthService auth;public AuthController(AuthService a){auth=a;}@PostMapping("/register")ApiResponse<?>register(@Valid@RequestBody Credentials r,HttpServletResponse s){return ok(auth.register(r.username(),r.password()),s);}@PostMapping("/login")ApiResponse<?>login(@Valid@RequestBody Credentials r,HttpServletResponse s){return ok(auth.login(r.username(),r.password()),s);}@PostMapping("/refresh")ApiResponse<?>refresh(@CookieValue(value="VM_REFRESH",required=false)String r,HttpServletResponse s){return ok(auth.refresh(r),s);}@PostMapping("/logout")ApiResponse<?>logout(@CookieValue(value="VM_REFRESH",required=false)String r,HttpServletResponse s){auth.revoke(r);cookie(s,"VM_ACCESS","",0);cookie(s,"VM_REFRESH","",0);return ApiResponse.success();}@GetMapping("/me")ApiResponse<?>me(){Long id=com.videomind.common.context.MockUserContext.currentUserId();var u=auth.user(id);return ApiResponse.success(Map.of("subject",u.getPublicId(),"username",u.getUsername()));}private ApiResponse<?>ok(AuthService.TokenPair p,HttpServletResponse s){cookie(s,"VM_ACCESS",p.accessToken(),900);cookie(s,"VM_REFRESH",p.refreshToken(),30*86400);return ApiResponse.success(Map.of("accessToken",p.accessToken(),"expiresIn",p.expiresIn(),"subject",p.subject(),"username",p.username()));}private void cookie(HttpServletResponse s,String n,String v,int age){Cookie c=new Cookie(n,v);c.setHttpOnly(true);c.setPath("/");c.setMaxAge(age);s.addCookie(c);}record Credentials(@NotBlank String username,@NotBlank@Size(min=8,max=128)String password){} }
